const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Rectangle([50, 25, 60, 32]); // Southern Iran bounding box

  const date1_start = '2021-12-13';
  const date1_end = '2021-12-15'; // December 14, 2021
  const date2_start = '2022-01-06';
  const date2_end = '2022-01-08'; // January 7, 2022

  const s1_collection = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .filter(ee.Filter.eq('orbitProperties_pass', 'DESCENDING'))
    .filter(ee.Filter.eq('resolution_meters', 10))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .filterBounds(geometry);

  // Function to calculate water area for a given date range
  const calculateWaterArea = async (startDate, endDate, periodName) => {
    let collection = s1_collection.filterDate(startDate, endDate);

    const collectionSize = await collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`No Sentinel-1 images found for ${periodName}.`);
      return { area: null, count: 0, cloud_perc: 0, images: 0 }; // Indicate calculation failure due to empty collection
    }

    // Sort by system:time_start and take the latest image, or mosaic if multiple are desired.
    // For specific date, taking the first or median is usually sufficient.
    // Let's take the median for robustness if multiple images exist.
    let image = collection.median().clip(geometry);

    // Apply radiometric calibration (if not already done by GEE for GRD)
    // and terrain correction (which is usually good for GRD).
    // GEE's S1_GRD automatically provides calibrated backscatter coefficients.

    // Convert VV to decibels if not already done. Sentinel-1 GRD data are typically in linear power units,
    // and we usually convert them to dB for analysis.
    // GEE's 'COPERNICUS/S1_GRD' already outputs gamma0 in linear units.
    // We explicitly convert to dB.
    image = image.select('VV').unitScale(-30, 0).log10().multiply(10); // Standard decibel conversion

    // Water detection using a threshold on VV polarization (e.g., -18 dB)
    // Values lower than the threshold are likely water.
    const waterMask = image.lt(-18); // Example threshold. Adjust based on region/sensor.

    // Calculate total water pixels
    const waterPixels = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(), // Sum of '1' for water pixels, '0' for land
      geometry: geometry,
      scale: 10, // Sentinel-1 native resolution
      maxPixels: 1e9
    });

    const totalWaterPixels = await waterPixels.get('VV').getInfo();

    if (totalWaterPixels === null) {
      console.log(`Calculation failure for ${periodName}: Water pixel count is null.`);
      return { area: null, count: 0, cloud_perc: 0, images: collectionSize }; // Indicate calculation failure
    }

    // Calculate total pixels in the geometry to check for C2
    const totalPixels = waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 10,
      maxPixels: 1e9
    });

    const validAreaPixels = await totalPixels.get('VV').getInfo();

    if (validAreaPixels === 0) {
      console.log(`No valid pixels remaining in the geometry after initial processing for ${periodName}.`);
      return { area: null, count: 0, cloud_perc: 0, images: collectionSize }; // Indicate C2
    }

    // Convert pixels to area (10m x 10m = 100 sq meters per pixel)
    const waterAreaSqKm = (totalWaterPixels * 10 * 10) / 1e6; // 10m * 10m = 100 sq m per pixel

    return { area: waterAreaSqKm, count: totalWaterPixels, cloud_perc: 0, images: collectionSize };
  };

  // 2. Data Acquisition & Check and 3. Processing
  let stats1 = await calculateWaterArea(date1_start, date1_end, 'Dec 14, 2021');
  let stats2 = await calculateWaterArea(date2_start, date2_end, 'Jan 7, 2022');

  // Check for C1 or C2
  if (stats1.area === null && stats1.images === 0 || stats2.area === null && stats2.images === 0) {
    console.log("Empty Collection (No images found for one or both comparison points).");
    console.log("C1");
    return;
  }
  if (stats1.area === null && stats1.count === 0 && stats1.images > 0 || stats2.area === null && stats2.count === 0 && stats2.images > 0) {
    console.log("No Valid Pixels (Images exist, but after processing, 0 pixels remain).");
    console.log("C2");
    return;
  }
  if (stats1.area === null || stats2.area === null) { // More general calculation failure check
    console.log("Calculation Failure (Result is None, NaN, or invalid).");
    console.log("C3");
    return;
  }

  // 4. Calculation
  const area1 = stats1.area;
  const area2 = stats2.area;

  // 5. Validation & Final Answer
  console.log(`Dec 14, 2021: Images: ${stats1.images}, Water Area: ${area1.toFixed(2)} sq km, Water Pixels: ${stats1.count}`);
  console.log(`Jan 7, 2022: Images: ${stats2.images}, Water Area: ${area2.toFixed(2)} sq km, Water Pixels: ${stats2.count}`);

  if (area2 > area1) {
    console.log("A"); // Yes, surface water extent increased
  } else {
    console.log("B"); // No, surface water extent did not increase
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
